"use client";

import { useId, useState } from "react";
import "./image-compare.css";

export interface ImageCompareProps {
  before: string;
  after: string;
  beforeAlt: string;
  afterAlt: string;
  beforeLabel?: string;
  afterLabel?: string;
  initial?: number;
}

/** Native range input supports pointer, touch, and keyboard without custom dragging. */
export function ImageCompare({
  before,
  after,
  beforeAlt,
  afterAlt,
  beforeLabel = "Before",
  afterLabel = "After",
  initial = 50,
}: ImageCompareProps) {
  const [position, setPosition] = useState(Math.max(0, Math.min(100, initial)));
  const id = useId();
  return (
    <div className="forme-compare">
      <img src={after} alt={afterAlt} loading="lazy" />
      <div
        className="forme-compare-before"
        style={{ clipPath: `inset(0 ${100 - position}% 0 0)` }}
      >
        <img src={before} alt={beforeAlt} loading="lazy" />
      </div>
      <span className="forme-compare-label before">{beforeLabel}</span>
      <span className="forme-compare-label after">{afterLabel}</span>
      <span
        className="forme-compare-divider"
        style={{ left: `${position}%` }}
        aria-hidden="true"
      >
        <span>↔</span>
      </span>
      <label htmlFor={id} className="forme-compare-sr">
        Comparison position
      </label>
      <input
        id={id}
        type="range"
        min="0"
        max="100"
        step="1"
        value={position}
        onChange={(e) => setPosition(Number(e.target.value))}
        aria-valuetext={`${position}% ${beforeLabel}, ${100 - position}% ${afterLabel}`}
      />
    </div>
  );
}

.forme-compare {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 280px;
  overflow: hidden;
  background: #343638;
  color: #fff;
}
.forme-compare > img,
.forme-compare-before,
.forme-compare-before > img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.forme-compare-label {
  position: absolute;
  top: 20px;
  font: 400 10px/1.2 sans-serif;
  background: #13171c85;
  padding: 7px 10px;
  border: 1px solid #ffffff40;
  backdrop-filter: blur(5px);
  border-radius: 3px;
  pointer-events: none;
}
.forme-compare-label.before {
  left: 20px;
}
.forme-compare-label.after {
  right: 20px;
}
.forme-compare-divider {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: #fffe;
  pointer-events: none;
}
.forme-compare-divider > span {
  position: absolute;
  top: 50%;
  left: 0;
  transform: translate(-50%, -50%);
  display: grid;
  place-items: center;
  width: 37px;
  height: 37px;
  background: #fff;
  color: #23282d;
  border-radius: 50%;
  box-shadow: 0 3px 20px #0003;
  font-size: 20px;
}
.forme-compare input {
  appearance: none;
  position: absolute;
  inset: 0;
  margin: 0;
  width: 100%;
  height: 100%;
  background: transparent;
  cursor: ew-resize;
  opacity: 0;
}
.forme-compare input::-webkit-slider-thumb {
  appearance: none;
  width: 35px;
  height: 100%;
  background: transparent;
}
.forme-compare input::-moz-range-thumb {
  width: 35px;
  height: 100%;
  border: 0;
  background: transparent;
}
.forme-compare:focus-within {
  outline: 3px solid #91b7e2;
  outline-offset: -4px;
}
.forme-compare-sr {
  position: absolute;
  clip-path: inset(50%);
  width: 1px;
  height: 1px;
  overflow: hidden;
}
